import numpy as np
B = 8.10461e-3
l1 = 1.1071
def code(wl):
    wl2=wl**2
    return np.sqrt(11.6858 + 0.939816/wl2 + B*wl2/(wl2-l1**2))
def ref(wl):
    wl2=wl**2
    return np.sqrt(11.6858 + 0.939816/wl2 + B*l1**2/(wl2-l1**2))
for wl in [1.2,1.31,1.55,2.0,3.0,5.0,10.6,14.0]:
    print(wl, f"{code(wl):.6f}", f"{ref(wl):.6f}", f"{code(wl)-ref(wl):+.6f}")
# n^2 offset check
for wl in [1.31,1.55,10.6]:
    print("n2 diff:", code(wl)**2-ref(wl)**2)
